from dataclasses import dataclass
from typing import List, Dict, Any, Optional

@dataclass
class ChatMessage:
    role: str
    content: str

@dataclass
class ModelRequest:
    messages: List[ChatMessage]
    model: str
    stream: Optional[bool] = False

@dataclass
class ModelResponseChoice:
    message: ChatMessage
    finish_reason: str

@dataclass
class ModelResponseUsage:
    prompt_tokens: int
    completion_tokens: int
    total_tokens: int

@dataclass
class ModelResponse:
    id: str
    model: str
    choices: List[ModelResponseChoice]
    usage: ModelResponseUsage
    created: int

from azure.cognitiveservices.vision.contentmoderator import ContentModeratorClient
from msrest.authentication import CognitiveServicesCredentials
import os

def platform_output_safety(text_output, config=None):
    config = config or {}
    subscription_key = os.environ.get("AZURE_CONTENT_MODERATOR_KEY", config.get("key"))
    endpoint = os.environ.get("AZURE_CONTENT_MODERATOR_ENDPOINT", config.get("endpoint"))

    if not all([subscription_key, endpoint]):
        raise ValueError("Azure Content Moderator key and endpoint must be provided.")

    client = ContentModeratorClient(
        endpoint=endpoint, credentials=CognitiveServicesCredentials(subscription_key)
    )

    # Text moderation
    # The Text moderation APIs are synchronous
    screen = client.text_moderation.screen_text(
        text_content=text_output, 
        language='eng',
        autocorrect=True,
        pii=True,
        classify=True
    )

    is_unsafe = False
    safety_results = {}

    if screen.classification:
        if screen.classification.category1.score > 0.5 or \
           screen.classification.category2.score > 0.5 or \
           screen.classification.category3.score > 0.5:
            is_unsafe = True
        safety_results["classification"] = {
            "category1": screen.classification.category1.score if screen.classification.category1 else 0,
            "category2": screen.classification.category2.score if screen.classification.category2 else 0,
            "category3": screen.classification.category3.score if screen.classification.category3 else 0,
            "review_recommended": screen.classification.review_recommended
        }

    if screen.terms:
        is_unsafe = True # If any terms are found, consider it unsafe
        safety_results["terms"] = [{
            "term": term.term,
            "index": term.index,
            "original_index": term.original_index
        } for term in screen.terms]

    return {"is_unsafe": is_unsafe, "safety_details": safety_results}

import requests
import uuid
import os

def localized_platform_output(text_output, target_locale, config=None):
    config = config or {}
    key = os.environ.get("AZURE_TRANSLATOR_TEXT_KEY", config.get("key"))
    endpoint = os.environ.get("AZURE_TRANSLATOR_TEXT_ENDPOINT", config.get("endpoint"))
    location = os.environ.get("AZURE_TRANSLATOR_TEXT_LOCATION", config.get("location")) # e.g., "global" or a specific region

    if not all([key, endpoint, location]):
        raise ValueError("Azure Translator Text key, endpoint, and location must be provided.")

    path = '/translate'
    constructed_url = endpoint + path

    headers = {
        'Ocp-Apim-Subscription-Key': key,
        'Ocp-Apim-Subscription-Region': location,
        'Content-type': 'application/json',
        'X-ClientTraceId': str(uuid.uuid4())
    }

    params = {
        'api-version': '3.0',
        'to': target_locale
    }

    body = [{'text': text_output}]

    request = requests.post(constructed_url, params=params, headers=headers, json=body)
    response = request.json()

    if request.status_code != 200:
        raise Exception(f"Translation failed with status code {request.status_code}: {response}")

    translated_text = response[0]['translations'][0]['text']
    return {"translated_text": translated_text, "source_text": text_output, "target_locale": target_locale}
